<?php
 namespace ehr; require_once(__DIR__ . '/../../../../init.php'); require_once(__DIR__ . '/../autoload.php'); interface iLink { const DEBUG = true, DB_CONNECT = 'medcard'; const DATE1900 = '1900-01-01T00:00:00'; const DATE3000 = '3000-01-01T00:00:00'; const SFT_RECIPE = 5, SFT_HOSPITAL = 10; const LOG_MSG_ALL = 0, LOG_MSG_FATAL = 1, LOG_MSG_ERROR = 2, LOG_MSG_WARN = 3, LOG_MSG_EDS = 4, LOG_MSG_INFO = 5, LOG_MSG_DEBUG = 6; const PARAM_ISEDS = 'isEDS', PARAM_TYPE = 'type', PARAM_ISARM = 'isArm', PARAM_PATIENT = 'patient', PARAM_DOCTOR = 'doctor'; } abstract class Link implements iLink { protected const TASK_NAME = 'EHR'; protected const LINK_SCOPE_DEF = 'EHR.Organization.Read'; protected $db; protected $params; protected $lstAllMsg; protected $lstFatalMsg; protected $lstErrorMsg; protected $lstWarnMsg; protected $lstEDSmsg; protected $lstInfoMsg; protected $lstDebugMsg; protected $accessScope; protected $accessToken; protected $defaultTimeOut; protected $currentTimeOut; protected $serverDateTime; protected $serverDate; protected $answerCode; protected $accessTimeLimit; protected $workFromARM; protected $modeEDS; public function __construct(LinkParams $aParams, $aTimeOut = Exchange::HTTP_TIMEOUT_DEF, $aAccessScope = '') { $this->db = $this->getConnetDb(); $this->accessTimeLimit = 0; $this->tempXML = ''; $this->tempXML2 = ''; $this->lstAllMsg = ''; $this->lstFatalMsg = ''; $this->lstErrorMsg = ''; $this->lstWarnMsg = ''; $this->lstEDSmsg = ''; $this->lstInfoMsg = ''; $this->lstDebugMsg = ''; $this->defaultTimeOut = Exchange::HTTP_TIMEOUT_DEF; $this->currentTimeOut = $aTimeOut; $this->accessScope = trim(empty($aAccessScope) ? self::LINK_SCOPE_DEF : $aAccessScope); $this->accessToken = ''; $this->params = $aParams; $this->initServerDateTime(); $this->answerCode = 200; $sft = $this->params->type; if (!in_array($sft, [self::SFT_HOSPITAL, self::SFT_RECIPE])) { $this->getLogger() ->addLog("В параметрах указан неверный тип - {$sft} - настройки!", '', Logger::LMT_FATAL, true); } $this->ls = new LinkSetup($this); $this->ls->loadLinkSetup($sft); $this->exchange = new Exchange($this); } public function __destruct() { unset($this->accessScope); unset($this->accessToken); unset($this->tempXML); unset($this->tempXML2); unset($this->flstAllMsg); unset($this->flstFatalMsg); unset($this->flstErrorMsg); unset($this->flstWarnMsg); unset($this->flstEDSmsg); unset($this->flstInfoMsg); unset($this->flstDebugMsg); $this->ls->clearLinkSetup(); unset($this->ls); unset($this->db); unset($this->exchange); unset($this->logger); } public function getResultLists(): array { return [ $this->lstAllMsg, $this->lstFatalMsg, $this->lstErrorMsg, $this->lstWarnMsg, (self::DEBUG ? $this->lstInfoMsg : ''), $this->lstEDSmsg ]; } public function getLs(): ?LinkSetup { return $this->ls; } public function getLogger(): ?Logger { if (empty($this->logger)) { $this->logger = new Logger($this); } return $this->logger; } public function getExchange(): ?Exchange { return $this->exchange; } public function getConnetDb(&$scope = null) { $db = ($scope ?? $this)->db; return $db ?? $db = connectDb(self::DB_CONNECT); } public function getDefaultTimeOut(): int { return $this->defaultTimeOut; } public function getAccessTimeLimit(): int { return $this->accessTimeLimit; } public function setAccessTimeLimit(int $limit): void { $this->accessTimeLimit = $limit; } public function getAnswerCode(): int { return $this->answerCode; } public function setAnswerCode(int $code): void { $this->answerCode = $code; } public function getAccessToken(): string { return $this->accessToken; } public function setAccessToken(string $token): void { $this->accessToken = $token; } public function getAccessScope(): string { return $this->accessScope; } public function getCurrentTimeOut(): int { return $this->currentTimeOut; } public function receiveAccessToken(): void { $exchange = $this->getExchange(); $exchange->getAccessToken(); if (!$exchange->validResult($this->answerCode)) { $this->getLogger()->addLog( "ошибка {$this->accessScope} получения ключа доступа к ЦОД: {$exchange->getErrorMessage()}", 'token', Logger::LMT_FATAL, true ); } } private function initServerDateTime(): void { $this->serverDateTime = $this->getServerDateTime(); } public function getServerDateTime(): string { return selectSqlValue($this->getConnetDb(), 'select current_timestamp'); } public function getServerDate(): string { return selectSqlValue($this->getConnetDb(), 'select current_date'); } public function correctNoticeDateIn(): void { $ls = $this->getLs(); $ls->setParams([ 'lastNoticeDateIn' => $this->getServerDateTime() ]); $ls->saveLinkSetup(); } public function correctNoticeDateOut(): void { $ls = $this->getLs(); $ls->setParams([ 'lastNoticeDateOut' => $this->getServerDateTime() ]); $ls->saveLinkSetup(); } public function correctSessionDate(): void { $ls = $this->getLs(); if (empty($this->lstFatalMsg) && empty($this->lstErrorMsg)) { $ls->setParams([ 'lastSessionDate' => $this->getServerDate() ]); $ls->saveLinkSetup(); } else { $btw = new \DateTime($this->getServerDate()); $btw->sub(new \DateInterval("P{$ls->dayLimitIn}D")); if ($ls->useDayLimitIn && (safe_strtotime($btw) > safe_strtotime($ls->lastSessionDate))) { $ls->setParams([ 'lastSessionDate' => $btw ]); $ls->saveLinkSetup(); } } } public function getWorkFromARM(): bool { return $this->params->isArm; } public function getEDSMode(): bool { return $this->params->isEDS; } public function getLstEDSmsg(): string { return $this->lstEDSmsg; } private function getCurrentParam(string $name) { return $this->params->{$name} ?? null; } public function transfer(): void { $this->initTransfer(); if (!$this->getLs()->getAllowedLink()) { exit(); } $this->receiveAccessToken(); } public function addListMessage(string $message, int $type = self::LOG_MSG_ALL): void { switch ($type) { case self::LOG_MSG_FATAL: $this->lstFatalMsg .= $message; break; case self::LOG_MSG_ERROR: $this->lstErrorMsg .= $message; break; case self::LOG_MSG_WARN: $this->lstWarnMsg .= $message; break; case self::LOG_MSG_EDS: $this->lstEDSmsg .= $message; break; case self::LOG_MSG_INFO: $this->lstInfoMsg .= $message; break; case self::LOG_MSG_DEBUG: $this->lstDebugMsg .= $message; break; default: $this->lstAllMsg .= $message; } } } 